const patch = "*** Begin Patch
*** Add File: api/index.php
+<?php
+declare(strict_types=1);
+session_start();
+header('Content-Type: application/json; charset=utf-8');
+header('Access-Control-Allow-Origin: ' . ($_SERVER['HTTP_ORIGIN'] ?? 'http://localhost:5173'));
+header('Access-Control-Allow-Credentials: true');
+header('Access-Control-Allow-Headers: Content-Type');
+header('Access-Control-Allow-Methods: GET, POST, DELETE, OPTIONS');
+if ($_SERVER['REQUEST_METHOD'] === 'OPTIONS') { http_response_code(204); exit; }
+
+function db(): PDO {
+    static $pdo;
+    if ($pdo) return $pdo;
+    $path = getenv('DB_PATH') ?: __DIR__ . '/../data/pixelmarket.sqlite';
+    if (!is_dir(dirname($path))) mkdir(dirname($path), 0775, true);
+    $pdo = new PDO('sqlite:' . $path, options: [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC]);
+    $pdo->exec('PRAGMA foreign_keys=ON');
+    $pdo->exec('CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP)');
+    $pdo->exec('CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY, slug TEXT UNIQUE NOT NULL, title TEXT NOT NULL, category TEXT NOT NULL, platform TEXT NOT NULL, region TEXT NOT NULL, description TEXT NOT NULL, image TEXT NOT NULL, popularity INTEGER DEFAULT 0)');
+    $pdo->exec('CREATE TABLE IF NOT EXISTS offers(id INTEGER PRIMARY KEY, product_id INTEGER NOT NULL REFERENCES products(id), seller TEXT NOT NULL, price REAL NOT NULL, old_price REAL, stock INTEGER DEFAULT 20)');
+    $pdo->exec('CREATE TABLE IF NOT EXISTS keys_inventory(id INTEGER PRIMARY KEY, offer_id INTEGER NOT NULL REFERENCES offers(id), license_key TEXT UNIQUE NOT NULL, sold INTEGER DEFAULT 0)');
+    $pdo->exec('CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), total REAL NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP)');
+    $pdo->exec('CREATE TABLE IF NOT EXISTS order_items(id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES orders(id), product_title TEXT NOT NULL, quantity INTEGER NOT NULL, price REAL NOT NULL, license_key TEXT NOT NULL)');
+    $count = (int)$pdo->query('SELECT COUNT(*) FROM products')->fetchColumn();
+    if (!$count) seed($pdo);
+    return $pdo;
+}
+
+function seed(PDO $p): void {
+    $games = [
+      ['Elden Ring','Action RPG','PC','Global','Rise, Tarnished. Explore the Lands Between in this acclaimed open-world action RPG.','ERLDN',4821,35.49,59.99],
+      ['Cyberpunk 2077: Ultimate Edition','RPG','PC','Europe','Become V, a mercenary outlaw going after a one-of-a-kind implant in Night City. Includes Phantom Liberty.','CYBER',3990,32.89,59.99],
+      ['Baldur’s Gate 3','RPG','PC','Global','Gather your party and return to the Forgotten Realms in this story-rich, next-generation RPG.','BG3PC',3682,47.99,59.99],
+      ['Hogwarts Legacy','Adventure','PlayStation 5','Europe','Experience Hogwarts in the 1800s and decide the fate of the wizarding world.','HOGW',2920,24.79,69.99],
+      ['Red Dead Redemption 2','Adventure','PC','Global','Arthur Morgan and the Van der Linde gang are outlaws on the run across America.','RDR2',2740,19.99,59.99],
+      ['EA Sports FC 25','Sports','Xbox Series X|S','Europe','The world’s game, powered by the biggest leagues and clubs.','FC25',2510,29.89,69.99],
+      ['Stardew Valley','Indie','PC','Global','Build the farm of your dreams, grow crops, raise animals, and become part of the community.','STAR',2360,8.49,14.99],
+      ['The Witcher 3: Wild Hunt','RPG','PC','Global','You are Geralt of Rivia, mercenary monster slayer. Your choices shape an epic story.','WITCH',2100,11.99,39.99],
+      ['Minecraft: Java & Bedrock Edition','Adventure','PC','Global','Explore your own unique world, survive the night, and create anything you can imagine.','MINE',1990,22.99,29.99],
+      ['God of War Ragnarök','Action','PlayStation 5','Europe','Embark on an epic and heartfelt journey as Kratos and Atreus struggle with holding on and letting go.','GOWR',1750,49.99,69.99],
+      ['Hades II','Indie','PC','Global','Battle beyond the Underworld using dark sorcery to take on the Titan of Time.','HADES',1620,24.50,29.99],
+      ['Helldivers 2','Action','PC','Global','Join the Helldivers and fight for freedom across a hostile galaxy.','HELL',1510,29.99,39.99]
+    ];
+    $g = $p->prepare('INSERT INTO products(slug,title,category,platform,region,description,image,popularity) VALUES(?,?,?,?,?,?,?,?)');
+    $o = $p->prepare('INSERT INTO offers(product_id,seller,price,old_price) VALUES(?,?,?,?)');
+    $k = $p->prepare('INSERT INTO keys_inventory(offer_id,license_key) VALUES(?,?)');
+    foreach ($games as $i=>$v) {
+      [$title,$cat,$platform,$region,$desc,$slug,$pop,$price,$old] = $v;
+      $g->execute([strtolower($slug),$title,$cat,$platform,$region,$desc,'https://images.unsplash.com/photo-'.['1542751371-adc38448a05e','1542751371-adc38448a05e','1511512578047-dfb367046420','1535223289827-42f1e9919769'][$i%4].'?auto=format&fit=crop&w=640&q=80',$pop]);
+      $pid=(int)$p->lastInsertId();
+      foreach ([['PixelVault',$price,$old],['GameHub',$price+1.65,null],['KeyHarbor',$price+3.20,null]] as [$seller,$amount,$was]) {
+        $o->execute([$pid,$seller,$amount,$was]); $oid=(int)$p->lastInsertId();
+        for($j=0;$j<25;$j++) $k->execute([$oid,sprintf('DEMO-%s-%04d-%04d',$slug,$i+1,$j+1)]);
+      }
+    }
+}
+function jsonBody(): array { return json_decode(file_get_contents('php://input'), true) ?? []; }
+function respond(mixed $data, int $status=200): never { http_response_code($status); echo json_encode($data, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); exit; }
+function requireUser(): int { if (empty($_SESSION['user_id'])) respond(['error'=>'Please sign in to continue.'],401); return (int)$_SESSION['user_id']; }
+function offersFor(PDO $p,int $id): array { $q=$p->prepare('SELECT id,seller,price,old_price,stock FROM offers WHERE product_id=? ORDER BY price'); $q->execute([$id]); return $q->fetchAll(); }
+function products(PDO $p,string $where='',array $args=[],string $sort='popularity'): array {
+    $sql='SELECT p.*,MIN(o.price) AS price,MAX(o.old_price) AS old_price FROM products p JOIN offers o ON o.product_id=p.id '.($where?'WHERE '.$where.' ':'').'GROUP BY p.id ORDER BY '.($sort==='price_asc'?'price ASC':($sort==='price_desc'?'price DESC':'p.popularity DESC'));
+    $q=$p->prepare($sql); $q->execute($args); $rows=$q->fetchAll(); foreach($rows as &$r){$r['offers']=offersFor($p,(int)$r['id']);} return $rows;
+}
+$p=db(); $method=$_SERVER['REQUEST_METHOD']; $path=parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH); $path=preg_replace('#^/api#','',$path); $body=jsonBody();
+if ($method==='GET' && $path==='/health') respond(['status'=>'ok','database'=>'sqlite']);
